<script setup>
import MButton from '../../../components/mds/MButton.vue'; import MEmptyState from '../../../components/mds/MEmptyState.vue'; import MMobileTopBar from '../../../components/mds/MMobileTopBar.vue'; import MSelect from '../../../components/mds/MSelect.vue';
defineProps({ title:String, currentOwnerLabel:String, currentOwnerId:[Number,String], owners:{type:Array,default:()=>[]}, ownerId:[Number,String], saving:Boolean, error:String, safeAreaStyle:Object }); const emit=defineEmits(['back','update:owner-id','submit']);
</script>
<template><section class="mds-mobile-app flex h-[100dvh] min-w-0 flex-col overflow-hidden bg-[var(--mds-bg)]" :style="safeAreaStyle"><MMobileTopBar title="Gán người phụ trách" @back="emit('back')"/><main class="min-h-0 flex-1 overflow-y-auto"><section class="mds-mobile-gutter-x py-4"><p class="text-[13px] text-[var(--mds-text-secondary)]">Giải thưởng</p><h1 class="mt-1 text-[18px] font-semibold">{{ title }}</h1><p class="mt-2 text-[13px] text-[var(--mds-text-secondary)]">Hiện tại: <strong>{{ currentOwnerLabel }}</strong></p><p class="mt-4 text-[13px] text-[var(--mds-text-secondary)]">Máy chủ sẽ kiểm tra lại quyền và tài khoản được chọn trước khi lưu.</p><MEmptyState v-if="!owners.length" class="mt-5" title="Không có tài khoản đang hoạt động" description="Chưa thể gán lại người phụ trách."/><div v-else class="mt-5"><label class="mb-1 block text-[13px] font-medium">Người phụ trách mới</label><MSelect :model-value="ownerId" :options="owners" placeholder="Chọn người phụ trách" @update:model-value="emit('update:owner-id',$event)"/><p v-if="error" role="alert" class="mt-3 text-[13px] text-[var(--mds-danger)]">{{ error }}</p></div></section></main><footer class="flex gap-2 border-t border-[var(--mds-border-light)] px-4 py-3 pb-[calc(12px+var(--mds-mobile-safe-bottom))]"><MButton variant="secondary" class="flex-1 [&]:h-[var(--mds-mobile-touch-target)]" @click="emit('back')">Hủy</MButton><MButton variant="primary" class="flex-1 [&]:h-[var(--mds-mobile-touch-target)]" :loading="saving" :disabled="!ownerId||Number(ownerId)===Number(currentOwnerId)" @click="emit('submit')">Xác nhận</MButton></footer></section></template>
